import { defineCollection, z } from 'astro:content';

const projects = defineCollection({
  type: 'content',
  schema: ({ image }) =>
    z.object({
      title: z.string(),
      summary: z.string(),
      tags: z.array(z.string()).min(1),
      href: z.string().url(),
      repo: z.string().url().optional(),
      order: z.number().int().nonnegative(),
      featured: z.boolean().default(true),
      motion: z.enum(['ripple', 'years']).optional(),
      // One still picture that shows the project at a glance, generated by scripts/work-art.
      art: z
        .object({
          image: image(),
          alt: z.string().min(1)
        })
        .optional()
    })
});

// Photos beside the name, one YAML entry per master, taking turns in one frame. `npm run photo` writes both.
const photos = defineCollection({
  type: 'data',
  schema: ({ image }) =>
    z.object({
      image: image(),
      alt: z.string().min(1),
      // Shown on the photo while it is up, so it stays short.
      caption: z.string().min(1).max(40),
      date: z.coerce.date(),
      // Where the crop keeps its middle, as "x% y%"; the middle of the photo when left out.
      position: z.string().regex(/^\d{1,3}% \d{1,3}%$/).optional()
    })
});

export const collections = {
  projects,
  photos
};
